// HllButton.jsx — generated by LightFX Studio, reorganized into
// /components/HllButton for this demo app.
// The canvas sits at z-index 0; slot content is wrapped at z-index 1 so it renders above the effect.
import { useEffect, useRef } from 'react';
import { LightComponent, cloneDefinition } from './lightfx-runtime.js';
import { DEFINITION } from './definition.js';

export default function HllButton({ as: Tag = 'div', className, style, children }) {
  const ref = useRef(null);
  useEffect(() => {
    const fx = new LightComponent(ref.current, cloneDefinition(DEFINITION));
    return () => fx.dispose();
  }, []);
  return (
    <Tag ref={ref} className={className} style={{ position: 'relative', ...style }}>
      <div style={{ position: 'relative', zIndex: 1 }}>{children}</div>
    </Tag>
  );
}
